39	 */
40	export function frameAt(run, ledger, fraction) {
41	  if (fraction >= 1) return { run, ledger };
42	  const { start, end } = runWindow(run, ledger);
43	  const now = start + Math.max(0, fraction) * (end - start);
44	
45	  const rows = [];
46	  for (const [index, row] of ledger.entries()) {
47	    const { began, ended } = rowWindow(row, index, start, end, ledger.length);
48	    if (began > now) continue;
49	    rows.push(ended <= now ? row : inFlight(row, (now - began) / Math.max(1, ended - began)));
50	  }
